(6607290, 985990, 96751, '<td valign="top">Who knew spoons could show so much personality!  Love the tones you achieved here, Lynn.</td>', 'Who knew spoons could show so much personality!  Love the tones you achieved here, Lynn.', '2011-12-01 05:45:55.000000', NULL, 1),
(6607291, 985881, 96751, '<td valign="top">Love how the pictures in the back are involved in the conversation</td>', 'Love how the pictures in the back are involved in the conversation', '2011-12-01 05:46:28.000000', NULL, 1),
