(6610342, 985889, 125975, '<td valign="top">This image is oddly attractive to me, even with the ropes hanging in front of the sheep.  I am a handspinner and love sheep though, so that may be part of the appeal.  All in all, I really like it.  It shows so much movement.</td>', 'This image is oddly attractive to me, even with the ropes hanging in front of the sheep.  I am a handspinner and love sheep though, so that may be part of the appeal.  All in all, I really like it.  It shows so much movement.', '2011-12-04 15:24:59.000000', NULL, 1),
(6610343, 985939, 125975, '<td valign="top">Nice Christmas picture.  Lovely portrait of a handsome family.  I like the soft, darker background with lights.</td>', 'Nice Christmas picture.  Lovely portrait of a handsome family.  I like the soft, darker background with lights.', '2011-12-04 15:25:56.000000', NULL, 1),
